import 'package:flutter/material.dart';

import '../state/app_locale_controller.dart';

/// Tradutor leve para os textos da interface do DailyTalk.pt.
///
/// O texto português funciona como identificador legível. Se uma tradução não
/// existir, o texto original é apresentado, evitando falhas na interface.
class AppTranslations {
  const AppTranslations._();

  static String translate(
    String source,
    String languageCode, {
    Map<String, Object?> parameters = const <String, Object?>{},
  }) {
    // Esta designação funciona como ponto de recuperação universal. Mesmo que
    // o utilizador escolha um idioma por engano, encontra sempre "Language"
    // escrito da mesma forma para poder regressar à configuração de idiomas.
    if (source == 'Language') {
      return source;
    }

    final language = normalizeAppLanguageCode(languageCode).split('-').first;
    var translated = language == 'pt'
        ? source
        : (_lookupExact(source, language) ??
            _translatePrefixed(source, language));

    for (final entry in parameters.entries) {
      translated = translated.replaceAll('{${entry.key}}', '${entry.value ?? ''}');
    }

    return translated;
  }

  static String? _lookupExact(String source, String language) {
    return _translations[language]?[source] ??
        _supplementalTranslations[language]?[source] ??
        _domainTranslations[language]?[source];
  }

  static String _translatePrefixed(String source, String language) {
    final prefixes = _prefixTranslations[language];
    if (prefixes != null) {
      for (final entry in prefixes.entries) {
        if (source.startsWith(entry.key)) {
          final remainder = source.substring(entry.key.length);
          final translatedRemainder = _lookupExact(remainder, language) ?? remainder;
          return '${entry.value}$translatedRemainder';
        }
      }
    }

    return source;
  }

